PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY, whatsapp TEXT NOT NULL UNIQUE, owner_name TEXT, gender TEXT, birth_day INTEGER, birth_month INTEGER, profile_completed INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active', registered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS member_vehicles (id TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id), plate_number TEXT NOT NULL, vehicle_type TEXT, brand TEXT, model TEXT, color TEXT, year INTEGER, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_categories (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, sku TEXT NOT NULL UNIQUE, category_id TEXT REFERENCES product_categories(id), name TEXT NOT NULL, unit TEXT NOT NULL, purchase_price INTEGER NOT NULL DEFAULT 0, selling_price INTEGER NOT NULL DEFAULT 0, stock_qty INTEGER NOT NULL DEFAULT 0, minimum_stock INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_categories (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, category_id TEXT REFERENCES service_categories(id), name TEXT NOT NULL, price INTEGER NOT NULL DEFAULT 0, estimated_minutes INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wallet_accounts (id TEXT PRIMARY KEY, member_id TEXT NOT NULL UNIQUE REFERENCES members(id), current_balance INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'IDR', status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wallet_ledger (id TEXT PRIMARY KEY, wallet_account_id TEXT NOT NULL REFERENCES wallet_accounts(id), member_id TEXT NOT NULL REFERENCES members(id), type TEXT NOT NULL CHECK (type IN ('credit','debit')), source_type TEXT NOT NULL, source_id TEXT NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0), balance_before INTEGER NOT NULL, balance_after INTEGER NOT NULL, reference_number TEXT NOT NULL UNIQUE, description TEXT, created_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deposits (id TEXT PRIMARY KEY, deposit_number TEXT NOT NULL UNIQUE, member_id TEXT NOT NULL REFERENCES members(id), amount INTEGER NOT NULL CHECK (amount > 0), method TEXT NOT NULL CHECK (method IN ('transfer','direct_admin')), bank_reference TEXT, proof_file TEXT, status TEXT NOT NULL DEFAULT 'pending', submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at TEXT, reviewed_by TEXT, rejection_reason TEXT, wallet_ledger_id TEXT REFERENCES wallet_ledger(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS point_ledger (id TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id), type TEXT NOT NULL, source_type TEXT NOT NULL, source_id TEXT NOT NULL, points INTEGER NOT NULL CHECK (points > 0), direction TEXT NOT NULL CHECK (direction IN ('credit','debit')), balance_before INTEGER NOT NULL, balance_after INTEGER NOT NULL, reference_number TEXT NOT NULL UNIQUE, description TEXT, created_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS point_conversions (id TEXT PRIMARY KEY, conversion_number TEXT NOT NULL UNIQUE, member_id TEXT NOT NULL REFERENCES members(id), points_used INTEGER NOT NULL, conversion_rate INTEGER NOT NULL, wallet_amount INTEGER NOT NULL, point_ledger_id TEXT NOT NULL REFERENCES point_ledger(id), wallet_ledger_id TEXT NOT NULL REFERENCES wallet_ledger(id), status TEXT NOT NULL DEFAULT 'completed', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS promotions (id TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL CHECK (type IN ('percentage','fixed')), value INTEGER NOT NULL, start_at TEXT NOT NULL, end_at TEXT NOT NULL, scope TEXT NOT NULL, member_only INTEGER NOT NULL DEFAULT 0, max_discount INTEGER, status TEXT NOT NULL DEFAULT 'draft', created_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sales_transactions (id TEXT PRIMARY KEY, transaction_number TEXT NOT NULL UNIQUE, member_id TEXT REFERENCES members(id), vehicle_id TEXT REFERENCES member_vehicles(id), cashier_user_id TEXT NOT NULL, transaction_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, subtotal INTEGER NOT NULL DEFAULT 0, discount_amount INTEGER NOT NULL DEFAULT 0, total_amount INTEGER NOT NULL DEFAULT 0, promo_id TEXT REFERENCES promotions(id), payment_status TEXT NOT NULL DEFAULT 'unpaid', transaction_status TEXT NOT NULL DEFAULT 'draft', notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transaction_items (id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL REFERENCES sales_transactions(id), item_type TEXT NOT NULL CHECK (item_type IN ('product','service')), product_id TEXT REFERENCES products(id), service_id TEXT REFERENCES services(id), item_name_snapshot TEXT NOT NULL, qty INTEGER NOT NULL, unit_price INTEGER NOT NULL, discount_percent INTEGER NOT NULL DEFAULT 0, discount_amount INTEGER NOT NULL DEFAULT 0, final_unit_price INTEGER NOT NULL, subtotal INTEGER NOT NULL, employee_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL REFERENCES sales_transactions(id), payment_method TEXT NOT NULL, amount INTEGER NOT NULL, wallet_ledger_id TEXT REFERENCES wallet_ledger(id), payment_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'completed', reference TEXT, created_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, user_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, before_data TEXT, after_data TEXT, ip_address TEXT, user_agent TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_members_whatsapp ON members(whatsapp);
CREATE INDEX IF NOT EXISTS idx_transactions_member_date ON sales_transactions(member_id, transaction_at);
CREATE INDEX IF NOT EXISTS idx_deposits_status ON deposits(status, submitted_at);
CREATE INDEX IF NOT EXISTS idx_wallet_ledger_member ON wallet_ledger(member_id, created_at);
CREATE INDEX IF NOT EXISTS idx_point_ledger_member ON point_ledger(member_id, created_at);
